        car.inventory_snapshots.WHERE(
            (snapshot_date == sale_date) & (is_in_inventory == False)
        )
    )
    == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make, model=car.model, sale_price=sale_price
)

total_sales_count = Dealership.CALCULATE(
